// NAT-130 adapter configuration — the single SOURCE_CRM switch.
// n8n blocks property access on $env on this instance, so the switch is read
// from n8n Variables first and falls back to the literal defaults below.
// Set a project Variable named SOURCE_CRM / SOURCE_CLIENT to change it.
function readVar(name) {
  try {
    const v = $vars;
    if (v && typeof v === 'object') {
      const val = v[name];
      if (val !== undefined && val !== null && String(val).trim() !== '') return String(val).trim();
    }
  } catch (e) { /* variable not defined, fall through */ }
  return null;
}

const rawCrm = (readVar('SOURCE_CRM') || 'zoho').toLowerCase();
const ENABLED = ['zoho'];
if (!ENABLED.includes(rawCrm)) {
  throw new Error('SOURCE_CRM=' + rawCrm + ' is not enabled in this adapter. Enabled: ' + ENABLED.join(', '));
}
const sourceClient = readVar('SOURCE_CLIENT') || 'growbusy-main';
if (!sourceClient) throw new Error('SOURCE_CLIENT resolved to empty');

const first = $input.first().json;
const c = first.payload ?? first;
if (!c || typeof c !== 'object') throw new Error('empty canonical payload');

const platform = String(c.source || '').trim().toLowerCase();
if (platform !== 'instagram' && platform !== 'facebook') {
  throw new Error('unsupported canonical.source: ' + JSON.stringify(c.source));
}
const socialId = String(c.userId || '').trim();
if (!socialId) throw new Error('canonical.userId (PSID) is required for identity');

return [{ json: {
  crm: rawCrm,
  sourceClient,
  reactivationDays: 30,
  consentVersion: String((c.consent && c.consent.version) || 'v1'),
  platform,
  socialId,
  personKey: platform + ':' + socialId,
  email: c.email ? String(c.email).trim().toLowerCase() : '',
  displayName: String(c.name || c.handle || 'Social lead').slice(0, 120),
  handle: c.handle ? String(c.handle) : null,
  postId: String(c.postId || c.mediaId || ''),
  permalink: c.permalink ? String(c.permalink) : null,
  message: c.message ? String(c.message).slice(0, 2000) : '',
  canonical: c
} }];

function safeGet(name) { try { return $(name).first().json; } catch (e) { return null; } }
function unwrapLead(raw) {
  if (!raw || typeof raw !== 'object') return null;
  if (Array.isArray(raw.data) && raw.data[0] && typeof raw.data[0] === 'object') return raw.data[0];
  return raw.id ? raw : null;
}
function contextDescription(c) {
  return [
    (c.platform === 'instagram' ? 'IG' : 'FB') + ' comment: ' + c.message,
    'Media: ' + (c.postId || 'n/a'),
    'externalId: ' + ((c.canonical && c.canonical.externalId) || 'n/a'),
    'PSID: ' + (c.socialId || 'n/a'),
    c.handle ? 'handle: ' + c.handle : null,
    'channel: ' + c.platform
  ].filter(Boolean).join('\n').slice(0, 2000);
}

const cfg = safeGet('1. Config and normalize');
if (!cfg) throw new Error('config node output unavailable');

const row = safeGet('2. Lookup identity') || {};
const raw = safeGet('4. Read lead from Zoho');
const zlead = unwrapLead(raw);
const leadLookupErrored = !!raw && !zlead;

const found = row.id !== undefined && row.id !== null;
const leadId = found ? (row.zoho_lead_id || null) : null;

const converted = !!(zlead && (
  zlead.Converted__s === true || zlead.Converted__s === 'true' ||
  (zlead.Converted_Contact && zlead.Converted_Contact.id) ||
  zlead['$converted'] === true
));

let reactivated = false;
if (found && row.last_seen_at) {
  const days = (Date.now() - new Date(row.last_seen_at).getTime()) / 86400000;
  reactivated = days > cfg.reactivationDays;
}

const matchedOn = !found ? 'none' : (row.matched_person_key ? 'socialId' : 'email');

let action, reason;
if (!found) { action = 'created'; reason = 'new person'; }
else if (leadId && leadLookupErrored) { action = 'created'; reason = 'linked zoho lead no longer exists, recreating'; }
else if (converted) { action = 'ignored'; reason = 'already a customer, comment dropped'; }
else { action = 'updated'; reason = reactivated ? ('returning after ' + cfg.reactivationDays + ' days or more') : 'repeat interest'; }

// Description guard: never write less than we read.
let descriptionToWrite = null;
if (action === 'updated') {
  if (!zlead) {
    descriptionToWrite = null;   // unreadable lead -> never write
  } else if (zlead.Description) {
    const line = '\u2014 ' + new Date().toISOString() + ' repeat interest via ' + cfg.platform + (cfg.postId ? (' post ' + cfg.postId) : '');
    descriptionToWrite = (String(zlead.Description) + '\n' + line).slice(0, 2000);
  } else {
    descriptionToWrite = contextDescription(cfg);   // genuinely empty -> write context, not a blank
  }
}

const zohoEmail = (zlead && zlead.Email) ? String(zlead.Email).trim().toLowerCase() : '';

return [{ json: {
  ...cfg,
  email: cfg.email || zohoEmail || (row.email || ''),
  action, reason, matchedOn, reactivated, converted,
  found,
  existingLeadId: leadId,
  lookupError: leadLookupErrored,
  leadWasRead: !!zlead,
  descriptionToWrite,
  contextDescription: contextDescription(cfg),
  existingDescription: (zlead && zlead.Description) ? String(zlead.Description) : '',
  existingStatus: (zlead && zlead.Lead_Status) ? String(zlead.Lead_Status) : null
} }];

const pick = (n) => { try { return $(n).first().json; } catch (e) { return null; } };
const row = $input.first().json || {};
const d = pick('8c. Attach lead id') || pick('5. Decide') || {};
return [{ json: {
  crm: d.crm || null,
  action: d.action || null,
  reason: d.reason || null,
  crmRecordId: d.zohoLeadId || d.existingLeadId || null,
  matchedOn: d.matchedOn || null,
  converted: d.converted === true,
  reactivated: d.reactivated === true,
  touches: (row && row.touches !== undefined && row.touches !== null) ? row.touches : null,
  personKey: d.personKey || null,
  platform: d.platform || null,
  canonical: d.canonical || null
} }];

const pick = (n) => { try { return $(n).first().json; } catch (e) { return null; } };
const d = pick('5. Decide');
if (!d) throw new Error('decide output unavailable');
const created = pick('8a. Create Zoho lead');
const updated = pick('8b. Update Zoho lead');
const lead = created || updated;
const id = lead && lead.id ? String(lead.id) : (d.existingLeadId || null);
return [{ json: { ...d, zohoLeadId: id, leadWasCreated: !!created } }];

